def file_extractor(filename):
    f= open(filename)
    f= f.readlines()

    model_dict={}
    params_dict={}

    for line in f:
        if 'model #' in line:
            temp=line.split("', '")
            model_num= None
            lr= None
            bs= None
            #print(temp[:13])
            for item in temp:
                if 'model #' in item:
                    model_num= item.split('# ')[-1]
                    model_num= int(model_num)
                if 'lr=' in item:
                    lr=item.split('=')[-1]
                    lr=float(lr)
                if 'bs' in item:
                    bs= int(item.split('=')[-1])
                    #print(bs)
            tuple_key= (lr, bs)
            if tuple_key not in model_dict:
                model_dict[tuple_key]= [model_num]
            else:
                model_dict[tuple_key].append(model_num)
            params_dict[model_num]=temp[:12]
    return model_dict, params_dict

